import string


def most_frequent_word(text):
    counts = {}
    for raw in text.split():
        word = raw.strip(string.punctuation).lower()
        if not word:
            continue
        counts[word] = counts.get(word, 0) + 1
    best = None
    for word, count in counts.items():
        if best is None or count > counts[best]:
            best = word
    return best
